import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as a,c as r,f as i,q as e,D as n,O as d,g as l}from"./chunks/runtime-core.esm-bundler.DabvBDJM.js";const p="/assets/img.D2iG18Nw.jpg",q=JSON.parse('{"title":"前端图片加载优化全链路方案","description":"","frontmatter":{},"headers":[],"relativePath":"column/前端进阶/性能优化/前端图片加载优化全链路方案.md","filePath":"column/前端进阶/性能优化/前端图片加载优化全链路方案.md","lastUpdated":1786410705000}'),c={name:"column/前端进阶/性能优化/前端图片加载优化全链路方案.md"};function g(h,t,u,b,m,k){const s=a("ArticleMetadata");return i(),r("div",null,[t[0]||(t[0]=e("h1",{id:"前端图片加载优化全链路方案",tabindex:"-1"},[l("前端图片加载优化全链路方案 "),e("a",{class:"header-anchor",href:"#前端图片加载优化全链路方案","aria-label":'Permalink to "前端图片加载优化全链路方案"'},"​")],-1)),n(s),t[1]||(t[1]=d('<blockquote><p>这篇文章从「图片为什么慢」出发，系统梳理前端图片优化的完整链路与各类方案，并用我的线上项目 Prompt Galler（图片提示词）的真实实践作为案例。</p><p>文中大部分方案是通用的，不绑定任何具体框架或云厂商，可直接套用到你自己的项目。</p><p><code>Prompt Galler</code> 线上地址：<a href="http://prompt.gouxinjie.com/" target="_blank" rel="noreferrer">http://prompt.gouxinjie.com/</a></p></blockquote><p><img src="'+p+`" alt="" loading="lazy"></p><h2 id="一、先理解-图片慢的本质" tabindex="-1">一、先理解：图片慢的本质 <a class="header-anchor" href="#一、先理解-图片慢的本质" aria-label="Permalink to &quot;一、先理解：图片慢的本质&quot;">​</a></h2><p>一张图片从用户点开页面到显示出来，经历了几个环节：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 图片体积多大   →  ② 有多少张要下载   →  ③ 走没走缓存   →  ④ 渲染时机对不对</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>任何一个环节没做好，都会让用户感觉「图片加载慢」或「每次进来都重新加载」。所以图片优化不是单点动作，而是一条<strong>全链路</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上传时压缩 → 格式选对 → 按需缩放 → 懒加载/预加载 → 长缓存 → 占位与降级</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>下面按这条链路逐个讲，每个环节都给出通用做法和本项目的落地参考。</p><p>把「一张图的一生」完整画出来，能看到优化点分布在哪：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 上传压缩 → ② 格式选对 → ③ 按需缩放 → ④ 加载时机 → ⑤ 长缓存 → ⑥ 占位降级</span></span>
<span class="line"><span>                                    （另：⑦ 外链与安全）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table tabindex="0"><thead><tr><th>环节</th><th>一句话</th><th>优化目标</th></tr></thead><tbody><tr><td>① 上传压缩</td><td>源头控制体积</td><td>存储/带宽↓</td></tr><tr><td>② 格式选对</td><td>选体积更小的格式</td><td>体积↓</td></tr><tr><td>③ 按需缩放</td><td>别下载原图</td><td>流量↓</td></tr><tr><td>④ 加载时机</td><td>首屏抢、非首屏缓</td><td>减少首屏请求数</td></tr><tr><td>⑤ 长缓存</td><td>别反复下载</td><td>减少重复请求</td></tr><tr><td>⑥ 占位降级</td><td>稳住体验</td><td>体验↑</td></tr><tr><td>⑦ 外链与安全</td><td>识别自有/第三方资源</td><td>安全↑</td></tr></tbody></table><ul><li>①②③ 决定「<strong>每张图传多大</strong>」；</li><li>④ 决定「<strong>什么时候传</strong>」；</li><li>⑤ 决定「<strong>还要不要重复传</strong>」；</li><li>⑥⑦ 决定「<strong>传的过程中体验稳不稳、安不安全</strong>」。</li></ul><h2 id="二、全链路优化方案" tabindex="-1">二、全链路优化方案 <a class="header-anchor" href="#二、全链路优化方案" aria-label="Permalink to &quot;二、全链路优化方案&quot;">​</a></h2><h3 id="环节-1-上传时压缩-源头控体积" tabindex="-1">环节 1：上传时压缩（源头控体积） <a class="header-anchor" href="#环节-1-上传时压缩-源头控体积" aria-label="Permalink to &quot;环节 1：上传时压缩（源头控体积）&quot;">​</a></h3><p>图片优化最好从源头做起——<strong>在用户上传时就控制原始体积</strong>，而不是等展示时再补救。</p><p><strong>通用做法：</strong></p><ul><li>前端用 Canvas 对图片做「压缩后上传」，常见库有 <code>browser-image-compression</code>、<code>compressorjs</code>。</li><li>压缩要点：限制最大边长（如 2000px）、JPG 质量 0.8 左右、EXIF 方向修正。</li><li>好处：原始存储体积变小，后续所有环节都受益。</li></ul><p><strong>顺手可用的线上压缩工具：</strong></p><ul><li><strong><a href="https://tinypng.com/" target="_blank" rel="noreferrer">TinyPNG</a></strong>：最经典的 PNG/JPG 压图工具，网页拖拽即用，对「单张几十张图、不想写代码」的场景最省事。它的压缩原理是智能降低色彩数量并优化编码，属于<strong>人眼几乎无感的近无损有损压缩</strong>，视觉几乎不变但体积能降一大截。也有 API（需注册 key）可集成到上传流程。</li><li><strong><a href="https://squoosh.app/" target="_blank" rel="noreferrer">Squoosh</a></strong>：Google 出品的在线图片压缩器，支持 AVIF/WebP/JPEG/PNG 等多种格式互转，可实时对比压缩前后质量与体积，适合「挑格式 + 调质量」一起完成。</li><li><strong><a href="https://github.com/svg/svgo" target="_blank" rel="noreferrer">TinyPNG 同族的 SVGO</a></strong>：面向 SVG 图标的压缩工具，适合压缩矢量图标资源。</li><li>其他可参考：<a href="https://kraken.io/" target="_blank" rel="noreferrer">Kraken.io</a>、<a href="https://compress-or-die.com/" target="_blank" rel="noreferrer">CompressOrDie</a>（支持 GIF）。</li></ul><blockquote><p>用法提示：设计稿或批量素材可以先用 TinyPNG/Squoosh 压一轮再上传；如果流程要求自动压缩，则优先考虑 <code>browser-image-compression</code>（前端）或对象存储的图片处理能力（后端/云函数），线上工具更多是「人工批量处理」的兜底手段。</p></blockquote><p><strong>本项目现状：</strong></p><ul><li>目前是 OSS 浏览器直传原图，上传时没做压缩，但限制了单图不超过 8MB。</li><li>原图较大时，靠「展示时缩放」兜底（见环节 3）。</li><li>若运营/管理员手动传图，可先用上面的线上工具压一遍，再走直传，能进一步省存储与带宽。</li></ul><blockquote><p>结论：如果追求极致，上传压缩是最值得做的一环，能从根本上减小存储与带宽成本。线上工具适合人工批量处理，自动化流程则用前端库或服务端图片处理。</p></blockquote><h3 id="环节-2-格式选对-体积立省-30-80" tabindex="-1">环节 2：格式选对（体积立省 30%~80%） <a class="header-anchor" href="#环节-2-格式选对-体积立省-30-80" aria-label="Permalink to &quot;环节 2：格式选对（体积立省 30%~80%）&quot;">​</a></h3><p>图片格式对体积影响巨大，优先级大致是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AVIF &gt; WebP &gt; JPEG &gt; PNG（同画质下）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>通用做法：</strong></p><ul><li>有透明通道的图形 → PNG / WebP。</li><li>无透明通道的照片 → JPEG / WebP / AVIF。</li><li>动图 → GIF / WebP（动画）。</li><li>现代浏览器基本都支持 WebP，条件允许上 AVIF。</li></ul><p><strong>本项目现状：</strong></p><ul><li>通过阿里云 OSS 图片处理服务，在<strong>加载时</strong>用 <code>?x-oss-process=image/format,jpg</code> 把 PNG 实时转成 JPG 返回，原图保持不变。</li><li>好处：不改原图、不引入服务端处理能力；代价是 JPG 对透明 PNG 会产生黑/白底、体积不如 WebP。</li></ul><blockquote><p>启示：格式转换不一定非要在上传时做死，像本项目这样「按需动态转换」也是一种灵活思路，但要注意透明背景和动图两个边界。</p></blockquote><h3 id="环节-3-按需缩放-别让用户下载原图" tabindex="-1">环节 3：按需缩放（别让用户下载原图） <a class="header-anchor" href="#环节-3-按需缩放-别让用户下载原图" aria-label="Permalink to &quot;环节 3：按需缩放（别让用户下载原图）&quot;">​</a></h3><p>这是本仓库最近重点优化的部分，也是最容易被忽略的一环。</p><p><strong>核心问题：</strong> 一张 3000px 的原图，在 400px 的卡片里展示，如果直接把原图地址塞给 <code>&lt;img&gt;</code>，浏览器下载的是完整原图——浪费了大量流量和时间。</p><p><strong>通用做法：</strong></p><ul><li>给不同展示尺寸准备不同大小的图片（<strong>响应式图片</strong>），用 <code>&lt;img srcset sizes&gt;</code> 让浏览器按视口挑合适的。</li><li>或用云厂商的图片处理服务，在 URL 上追加缩放参数，实时生成缩略图（本项目正是这种）。</li></ul><p><strong>本项目落地：</strong> 封装了统一的图片地址工具 <code>toDisplayImageUrl</code>，第二个参数指定目标宽度：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 列表缩略图用 900px，大图位用 1600px，小格子用 200px</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toDisplayImageUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(caseItem.coverUrl, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">900</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 首页卡片</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toDisplayImageUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(activeCover, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 详情主图</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toDisplayImageUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(image, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 封面缩略图</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>这些 <code>w_XXX</code> 数字是什么？</strong> 它们是 OSS 图片处理 URL 参数的一部分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原图 URL ? x-oss-process=image/format,jpg/resize,w_900</span></span>
<span class="line"><span>         ↑                         ↑↑  ↑↑        ↑↑↑</span></span>
<span class="line"><span>        原始图片地址                转JPG       限制宽度900px</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>也就是 <code>resize,w_900</code> 告诉 OSS：<strong>把这张图在服务端实时缩到 900px 宽再返回</strong>（高度等比，不拉伸）。这样浏览器拿到的就是一张 900px 的小图，而不是几 MB 的原图。</p><p><strong>项目里为什么用 <code>1200 / 1600 / 900 / 480 / 200</code> 这几档？</strong> 因为不同展示位的「物理需要」不同，档位就是按「该位置的渲染宽度 × DPR」来定的：</p><table tabindex="0"><thead><tr><th>档位</th><th>用在哪</th><th>对应渲染宽度（CSS px）</th><th>覆盖 DPR</th></tr></thead><tbody><tr><td><code>w_1600</code></td><td>详情主图、首页 Hero 大图</td><td>约 600~800</td><td>2x 高清屏</td></tr><tr><td><code>w_1200</code></td><td>中等大图（默认档，未指定 width 时的兜底）</td><td>约 500~600</td><td>2x</td></tr><tr><td><code>w_900</code></td><td>首页卡片、收藏卡片、详情参考图/相关推荐</td><td>约 300~500</td><td>2x</td></tr><tr><td><code>w_480</code></td><td>后台表格缩略图、投稿小图</td><td>约 80~240</td><td>2x</td></tr><tr><td><code>w_200</code></td><td>详情页封面切换小缩略图</td><td>约 76~100</td><td>2x</td></tr></tbody></table><ul><li><strong>档位偏低</strong>（如 400px 卡片却给 <code>w_200</code>）→ 图被浏览器放大 → <strong>发糊</strong>（本项目就踩过，把卡片从 <code>w_480</code> 提到 <code>w_900</code>）。</li><li><strong>档位偏高</strong>（小格子却给 <code>w_1600</code>）→ 等于下载接近原图的图 → <strong>白费流量</strong>。</li><li><strong>默认档 <code>w_1200</code></strong>：当调用方不传 width 时（如大图预览弹层、上传组件预览），兜底用 1200，保证「不放任下载原图」又足够清晰。</li></ul><p>宽度的选择依据是一个朴素的公式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标宽度 = 图片实际渲染 CSS 宽度 × 设备像素比(DPR)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>普通屏 DPR = 1：<code>渲染宽度</code> 即可。</li><li>Retina 屏 DPR = 2：需要 <code>渲染宽度 × 2</code> 的源图才不糊。</li><li>这也是为什么本项目把卡片从 <code>w_480</code> 提到 <code>w_900</code>、大图位用到 <code>w_1600</code>——<strong>低档会糊，高档费流量</strong>，要取「刚好覆盖 DPR 又不过度」的值。</li></ul><blockquote><p>关键点：OSS 的 <code>resize</code> 默认「只缩小不放大」，所以即使传了比原图还大的宽度，也会原样返回，不用担心放大变糊。</p></blockquote><h3 id="环节-4-加载时机-懒加载与预加载" tabindex="-1">环节 4：加载时机（懒加载与预加载） <a class="header-anchor" href="#环节-4-加载时机-懒加载与预加载" aria-label="Permalink to &quot;环节 4：加载时机（懒加载与预加载）&quot;">​</a></h3><p>下载体量确定后，还要控制「什么时候下载」。</p><p><strong>通用做法：</strong></p><ul><li><strong>懒加载</strong>：非首屏图片用 <code>loading=&quot;lazy&quot;</code>，滚动到才加载，减少首屏请求。</li><li><strong>预加载</strong>：首屏最重要的图用 <code>fetchpriority=&quot;high&quot;</code> 或 <code>&lt;link rel=&quot;preload&quot; as=&quot;image&quot;&gt;</code>，尽早抢占带宽。</li><li><strong>优先加载</strong>：首屏前几张大图可设置较高的加载优先级。</li></ul><p><strong>本项目现状：</strong></p><ul><li>首页 Hero 前 2 张图 <code>loading=&quot;eager&quot;</code> + 首张 <code>fetchPriority=&quot;high&quot;</code>，其余卡片 <code>loading=&quot;lazy&quot;</code>。</li><li>列表卡片统一 <code>loading=&quot;lazy&quot;</code> + <code>decoding=&quot;async&quot;</code>，避免阻塞主线程解码。</li></ul><blockquote><p>口诀：<strong>首屏关键图抢加载，非首屏图片缓加载。</strong></p></blockquote><h3 id="环节-5-长缓存-解决「每次进来都重新加载」" tabindex="-1">环节 5：长缓存（解决「每次进来都重新加载」） <a class="header-anchor" href="#环节-5-长缓存-解决「每次进来都重新加载」" aria-label="Permalink to &quot;环节 5：长缓存（解决「每次进来都重新加载」）&quot;">​</a></h3><p>用户最常抱怨的「我明明看过了，怎么每次进来还重新加载」，多半是<strong>缓存策略没做好</strong>。</p><p><strong>通用做法：</strong></p><ul><li>给图片这类「内容不可变」的资源设长缓存：<code>Cache-Control: public, max-age=31536000, immutable</code>，首次拿到后一年不再重新请求。</li><li>文件名带 hash（内容变化自动换 URL），配合 <code>immutable</code> 实现「内容不变永远不重新下载」。</li></ul><p><strong>在哪配、怎么配？</strong> 任选一层即可：</p><ul><li><strong>对象存储（OSS）</strong>：控制台 → Bucket → 传输管理 → 设置 HTTP 头，对图片目录追加上面的 <code>Cache-Control</code>。</li><li><strong>CDN</strong>：控制台 → 域名管理 → 缓存配置 → 添加规则，对图片扩展名/目录设 TTL（如 365 天）。若图片 URL 带 <code>x-oss-process</code> 等处理参数，需确认 CDN <strong>透传参数</strong>并单独给这类路径配缓存。</li></ul><p><strong>本项目踩过的坑：</strong> 开发时发现图片「每次进来都重新加载」，排查后是 <strong>DevTools 勾了 Disable cache</strong> 导致浏览器强制不走缓存——不是代码问题。生产环境静态图由浏览器磁盘缓存兜底，配合 OSS/CDN 长缓存即可。</p><blockquote><p>排障口诀：<strong>遇到「图片没缓存」，先看浏览器设置和 Network 响应头，别急着改代码。</strong></p></blockquote><h3 id="环节-6-占位与降级-提升感知体验" tabindex="-1">环节 6：占位与降级（提升感知体验） <a class="header-anchor" href="#环节-6-占位与降级-提升感知体验" aria-label="Permalink to &quot;环节 6：占位与降级（提升感知体验）&quot;">​</a></h3><p>即使前面都做了，图片加载仍有个空窗期，需要「占位」和「降级」兜底。</p><p><strong>通用做法：</strong></p><ul><li><strong>占位</strong>：固定 <code>width/height</code> 或 <code>aspect-ratio</code>，避免图片加载期间布局抖动（CLS）。</li><li><strong>骨架/占位色</strong>：图片未到前显示底色或模糊占位（LQIP）。</li><li><strong>降级</strong>：图片加载失败时切到占位图或提示，不让页面出现破图。</li></ul><p><strong>本项目现状：</strong></p><ul><li>卡片用 <code>aspect-ratio: 4/5</code> 占位，防止瀑布流列高塌陷。</li><li>首页热门条对加载失败的封面图做 <code>onError</code> 切换占位样式。</li></ul><h3 id="环节-7-外链与安全-别忘了非自有图片" tabindex="-1">环节 7：外链与安全（别忘了非自有图片） <a class="header-anchor" href="#环节-7-外链与安全-别忘了非自有图片" aria-label="Permalink to &quot;环节 7：外链与安全（别忘了非自有图片）&quot;">​</a></h3><p>前面的优化都假设图片存自己的 OSS/CDN，但真实项目里经常有<strong>外链图片</strong>（用户粘贴的 GitHub、Gitee、其他 CDN 链接），这一类要单独考虑。</p><p><strong>通用做法：</strong></p><ul><li><strong>外链不盲目追加处理参数</strong>：第三方图片的域名、规则不受你控制，乱拼参数可能返回错误或被拒绝。</li><li><strong>识别是否自有资源</strong>：判断域名是否属于你的 OSS/CDN（白名单），属于才处理，否则原样返回。</li><li><strong>安全</strong>：若做「同源代理下载」（本项目的 <code>/api/download-image</code>），必须校验目标域名白名单，防 SSRF；也要限制下载大小，防超大文件拖垮服务。</li></ul><p><strong>本项目现状：</strong></p><ul><li><code>toDisplayImageUrl</code> 先判断是否 OSS 图片：优先看 <code>objectKey</code>（非空即 OSS），老数据按域名特征（<code>.aliyuncs.com</code> 等）兜底，<strong>非 OSS 外链直接返回原 URL、不追加任何参数</strong>。</li><li>下载走 <code>/api/download-image</code> 同源代理，服务端白名单校验目标域名、限制最大 20MB、限制重定向次数，防 SSRF 与超大资源。</li></ul><h2 id="三、如何验证优化效果" tabindex="-1">三、如何验证优化效果 <a class="header-anchor" href="#三、如何验证优化效果" aria-label="Permalink to &quot;三、如何验证优化效果&quot;">​</a></h2><p>优化做完，要有办法确认「真的变快了」，别凭感觉：</p><ol><li><strong>Network 面板</strong>：看每张图的 <code>Size</code>（传输体积）、<code>Time</code>（耗时）、<code>Content Download</code>（下载耗时）。命中缓存会显示 <code>(from disk cache)</code>、Size 列变 <code>0 B</code>。</li><li><strong>Lighthouse</strong>：跑 Performance，看 <strong>LCP（最大内容绘制）</strong> 和 <strong>图片加载字节数</strong>。首屏图优化直接体现在 LCP 上。</li><li><strong>Performance 面板 / 真实用户监控（RUM）</strong>：看图片请求瀑布流、是否有被阻塞或超时的大图。</li><li><strong>体积预算</strong>：给首页设「首屏图片总字节数」红线（如 &lt; 500KB），超了就报警，防止后续迭代又把原图塞回来。</li></ol><blockquote><p>记住一个反直觉的坑：<strong>开发时勾选 DevTools 的 Disable cache，会强制所有图片重新下载</strong>，让你误以为「图片没缓存、每次重载」。验证缓存效果时务必取消勾选，看真实响应头。</p></blockquote><h2 id="四、一条判断清单-你的图片该优先优化哪一环" tabindex="-1">四、一条判断清单：你的图片该优先优化哪一环 <a class="header-anchor" href="#四、一条判断清单-你的图片该优先优化哪一环" aria-label="Permalink to &quot;四、一条判断清单：你的图片该优先优化哪一环&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先排查</th><th>对应环节</th></tr></thead><tbody><tr><td>图片很大、加载很慢</td><td>是不是直接用了原图？</td><td>环节 3 按需缩放</td></tr><tr><td>首屏一堆请求</td><td>是不是没做懒加载/预加载？</td><td>环节 4</td></tr><tr><td>每次进来都重新加载</td><td>是不是没有长缓存 / 开了 Disable cache？</td><td>环节 5</td></tr><tr><td>图片发糊</td><td>缩略图档位是不是低于 <code>渲染宽度 × DPR</code>？</td><td>环节 3</td></tr><tr><td>图片多、存储贵</td><td>上传时压缩 / 换 WebP 有没有做？</td><td>环节 1、2</td></tr><tr><td>页面图片来回跳动</td><td>有没有给 img 定宽高 / aspect-ratio？</td><td>环节 6</td></tr><tr><td>有外链图片</td><td>是否误给第三方图追加参数 / 代理下载有无白名单校验？</td><td>环节 7</td></tr></tbody></table><h2 id="五、进阶方案-再往深做" tabindex="-1">五、进阶方案（再往深做） <a class="header-anchor" href="#五、进阶方案-再往深做" aria-label="Permalink to &quot;五、进阶方案（再往深做）&quot;">​</a></h2><p>如果上面的基础优化做完还嫌不够，可以考虑：</p><ol><li><strong>响应式图片 <code>srcset/sizes</code></strong>：让同一张图在不同屏幕密度下选不同档位，比「单一固定宽度」更精细。</li><li><strong>CDN 边缘缓存与动态转换</strong>：用 CDN 的图片处理能力，把「格式转换 + 缩放 + 缓存」都在边缘节点完成，回源压力小。</li><li><strong>Service Worker + Cache Storage</strong>：离线可用、二次访问秒开，但对静态图片这种「本来就该长缓存」的资源收益有限，慎用。</li><li><strong>图片统计与预算</strong>：给关键页（如首页）设「首屏图片体积预算」，用 Lighthouse / Performance 持续监控，防止优化被后续迭代破坏。</li><li><strong>智能格式协商</strong>：服务端根据请求头的 <code>Accept</code> 返回 WebP/AVIF，现代浏览器优先拿小格式。</li></ol><h2 id="六、本项目完整实践对照" tabindex="-1">六、本项目完整实践对照 <a class="header-anchor" href="#六、本项目完整实践对照" aria-label="Permalink to &quot;六、本项目完整实践对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优化点</th><th>本项目做法</th></tr></thead><tbody><tr><td>上传压缩</td><td>未做（限制单图 8MB，建议用线上工具/前端库补充）</td></tr><tr><td>格式转换</td><td>OSS 加载时实时转 JPG（<code>format,jpg</code>）</td></tr><tr><td>按需缩放</td><td>公共工具 <code>toDisplayImageUrl(url, width)</code> 分级缩放</td></tr><tr><td>加载时机</td><td>首屏 eager+high，非首屏 lazy+async</td></tr><tr><td>长缓存</td><td>依赖浏览器磁盘缓存 + OSS/CDN 长缓存</td></tr><tr><td>占位降级</td><td><code>aspect-ratio</code> 占位 + 加载失败切占位样式</td></tr><tr><td>外链与安全</td><td>非 OSS 外链不追加参数；代理下载白名单 + 限大小</td></tr></tbody></table><h2 id="七、总结" tabindex="-1">七、总结 <a class="header-anchor" href="#七、总结" aria-label="Permalink to &quot;七、总结&quot;">​</a></h2><p>前端图片优化是一条<strong>从上传到展示的全链路</strong>，不是一个点：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上传时压缩 → 格式选对 → 按需缩放 → 懒加载/预加载 → 长缓存 → 占位与降级</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>源头</strong>控制原始体积，<strong>展示</strong>按需缩放，<strong>时机</strong>上首屏抢加载、非首屏缓加载，<strong>缓存</strong>上让静态资源长驻，<strong>兜底</strong>上用占位与降级稳住体验，<strong>安全</strong>上对外链资源做识别与白名单校验。</li><li>最容易被忽略也最值得先做的两件事：<strong>按需缩放</strong>（别下载原图）和<strong>长缓存</strong>（别反复下载）。</li><li>遇到「图片每次重新加载」这类问题，先查浏览器设置和响应头，再考虑改代码。</li><li>优化做完要<strong>用数据验证</strong>（Network / Lighthouse / LCP），别只凭「感觉快了不少」。</li></ul><p>一句话：<strong>图片优化的本质，是用最小的传输体积 + 最合适的加载时机 + 最持久的缓存复用，换最快的首屏与最省的成本。</strong></p>`,91))])}const P=o(c,[["render",g]]);export{q as __pageData,P as default};
